# DK HAS.  Haderslev Syd - Årøsund Havn
#
let ha = path("d3.dk.has");

with detail = 3, railway = :first :g1000 :pax :removed {
    # point.dk.Haderslev-Syd  dk.HVA

    with link = "line.dk.HAS" {
        track(ha[:has.ya, :bro - 0.49sw]);
    }

    with link = "point.dk.Brorsbøl", railway = :station {
        track(ha[:bro - 0.5sw, :bro + 0.5sw]);
        marker(:left :de.hp, ha[:bro] << 0.5lt);
        slabel(:right, ha[:bro] << 0.5lt << 1sh + (1dt, 1dt),
            "Brorsbøl"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:bro + 0.49sw, :van - 0.49sw]);
    }

    with link = "point.dk.Vandling", railway = :station {
        track(ha[:van - 0.5sw, :van + 0.5sw]);
        marker(:right :de.bf, ha[:van] >> 0.5lt);
        slabel(:right, ha[:van] << 0.5lt + (1.2dt, 1.1dt),
            "Vandling"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:van + 0.49sw, :van + 1.41km]);
        line_label(:right:se, ha[:van + 1.4km] >> 0.5lt, "HAS");
        track(ha[:van + 1.39km, :nvi - 0.49sw]);
    }

    with link = "point.dk.Nørre-Vilstrup", railway = :station {
        track(ha[:nvi - 0.5sw, :nvi + 0.5sw]);
        marker(:left :de.bf, ha[:nvi] << 0.5lt);
        slabel(:left, ha[:nvi] >> 0.5lt + (-1.2dt, 1.1dt),
            "Nørre Vilstrup"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:nvi + 0.49sw, :svi - 0.49sw]);
    }

    with link = "point.dk.Sønder-Vilstrup", railway = :station {
        track(ha[:svi - 0.5sw, :svi + 0.5sw]);
        marker(:right :de.bf, ha[:svi] >> 0.5lt);
        slabel(:bottom, ha[:svi] >> 0.5lt >> 1sh + (-2dt, 0.5dt),
            "Sønder Vilstrup"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:svi + 0.49sw, :kje - 0.49sw]);
    }

    with link = "point.dk.Kjelstrup-Bad", railway = :station {
        track(ha[:kje - 0.5sw, :kje + 0.5sw]);
        marker(:right :de.bf, ha[:kje] >> 0.5lt);
        slabel(:bottom, ha[:kje] >> 0.5lt >> 1sh + (4dt, 0.5dt),
            "Kjelstrup (Bad)"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:kje + 0.49sw, :olu - 0.49sw]);
    }

    with link = "point.dk.Olufskær", railway = :station {
        track(ha[:olu - 0.5sw, :olu + 0.5sw]);
        marker(:left :de.hp, ha[:olu] << 0.5lt);
        slabel(:top, ha[:olu] << 0.5lt << 1sh + (-0.5dt, -0.4dt),
            "Olufskær"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:olu + 0.49sw, :hej - 0.49sw]);
    }

    with link = "point.dk.Hejsager", railway = :station {
        track(ha[:hej - 0.5sw, :hej + 0.5sw]);
        marker(:left :de.bf, ha[:hej] << 0.5lt);
        slabel(:top, ha[:hej] << 0.5lt << 1sh + (-0.5dt, -0.4dt),
            "Hejsager"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:hej + 0.49sw, :hal - 0.49sw]);
    }

    with link = "point.dk.Halk", railway = :station {
        track(ha[:hal - 0.5sw, :hal + 0.5sw]);
        marker(:right :de.bf, ha[:hal] >> 0.5lt);
        slabel(:right, ha[:hal] >> 0.5lt >> 1sh + (1.2dt, 1.1dt),
            "Halk"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:hal + 0.49sw, :sod - 0.49sw]);
    }

    with link = "point.dk.Sode", railway = :station {
        track(ha[:sod - 0.5sw, :sod + 0.5sw]);
        marker(:left :de.hp, ha[:sod] << 0.5lt);
        slabel(:right, ha[:sod] >> 0.5lt + (1dt, 1dt),
            "Sode"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:sod + 0.49sw, :hyr - 0.49sw]);
    }

    with link = "point.dk.Hyrup", railway = :station {
        track(ha[:hyr - 0.5sw, :hyr + 0.5sw]);
        marker(:right :de.bf, ha[:hyr] >> 0.5lt);
        slabel(:right, ha[:hyr] >> 0.5lt >> 1sh + (1.2dt, 1.1dt),
            "Hyrup"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:hyr + 0.49sw, :hyr + 1.61km]);
        line_label(:right:w, ha[:hyr + 1.6km] >> 0.5lt, "HAS");
        track(ha[:hyr + 1.59km, :osb - 0.49sw]);
    }

    with link = "point.dk.Øsby", railway = :station {
        track(ha[:osb - 0.5sw, :osb + 0.5sw]);
        marker(:left :de.bf, ha[:osb] << 0.5lt);
        slabel(:left, ha[:osb] << 0.5lt << 1sh + (-1.3dt, 0.8dt),
            "Øsby"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:osb + 0.49sw, :haj - 0.49sw]);
    }

    with link = "point.dk.Hajstrup", railway = :station {
        track(ha[:haj - 0.5sw, :haj + 0.5sw]);
        marker(:left :de.bf, ha[:haj] << 0.5lt);
        slabel(:left, ha[:haj] << 0.5lt << 1sh + (2dt, -1.2dt),
            "Hajstrup"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:haj + 0.49sw, :rad - 0.49sw]);
    }

    with link = "point.dk.Råde", railway = :station {
        track(ha[:rad - 0.5sw, :rad + 0.5sw]);
        marker(:right :de.bf, ha[:rad] >> 0.5lt);
        slabel(:bottom, ha[:rad] >> 0.5lt >> 1sh + (0.3dt, 0.3dt),
            "Råde"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:rad + 0.49sw, :arb - 0.49sw]);
    }

    with link = "point.dk.Årøsund-By", railway = :station {
        track(ha[:arb - 0.5sw, :arb + 0.5sw]);
        marker(:left :de.hp, ha[:arb] << 0.7lt);
        slabel(:right, ha[:arb] >> 0.5lt + (1dt, 1.2dt),
            "Årøsund By"
        );
    }

    with link = "line.dk.HAS" {
        track(ha[:arb + 0.49sw, :arh - 0.49sw]);
    }

    with link = "point.dk.Årøsund-Havn", railway = :station {
        track(ha[:arh - 0.5sw, :arh + 0.5sw]);
        marker(:right :de.bf, ha[:arh] >> 0.7lt);
        slabel(:top, ha[:arh] << 0.5lt << 0.5dt,
            span(:bold, "Årøsund Havn")
        );
    }
}

